<div class="material-question"><div class="toolbar"><strong>Quiz question</strong><button type="button" class="btn small danger" data-remove-question>Remove</button></div><label>Question<input name="questions[{{ $index }}][prompt]" required maxlength="1000" value="{{ $question['prompt'] ?? '' }}"></label><div class="form-grid">@for($option=0;$option<4;$option++)<label>Choice {{ $option+1 }}<input name="questions[{{ $index }}][options][{{ $option }}]" required maxlength="500" value="{{ $question['options'][$option] ?? '' }}"></label>@endfor</div><label>Correct answer<select name="questions[{{ $index }}][correct]">@for($option=0;$option<4;$option++)<option value="{{ $option }}" @selected(($question['correct'] ?? 0)==$option)>Choice {{ $option+1 }}</option>@endfor</select></label></div>
